    # Find the uniform divider, then compare the two panels cell by cell.
    for r in range(h):
        if len(set(grid[r])) == 1:
            left, right = grid[:r], grid[r + 1:]
            if left and right and len(left) == len(right):
                shared = ({x for row in left for x in row} &
                          {x for row in right for x in row})
                if shared:
                    color = min(shared)
                    return [[3 if left[i][j] == color and right[i][j] == color
                             else color for j in range(w)]
                            for i in range(len(left))]

    for c in range(w):
        if len({grid[i][c] for i in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if left and right and len(left[0]) == len(right[0]):
                shared = ({x for row in left for x in row} &
                          {x for row in right for x in row})
